"""Extract documentation examples into build-only C# fixtures.

Place a snippet context comment above each C# fence. Select core, unity, or
integration, then file, members, statements, or async. For statements and
async, add the C# parameter declarations that the example assumes.
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from pathlib import Path
from re import compile as pattern

ROOT = Path(__file__).resolve().parents[2]
FOOTER = "_Snippet compiled in CI._"
FENCE = pattern(r" {0,3}(`{3,}|~{3,})(.*)")
CONTEXT = pattern(
    r"<!-- snippet: (core|unity|integration) (file|members|statements|async)(?: (.+))? -->"
)
CSHARP = {"csharp", "cs", "c#"}

DIALOGUE_MESSAGES = """// <auto-generated/>
namespace WallstopStudios.DxAudio.Documentation
{
    using DxMessaging.Core.Messages;
    using UnityEngine;

    public readonly struct DialogueStarted : IUntargetedMessage<DialogueStarted>
    {
        public GameObject speaker { get; }
    }

    public readonly struct DialogueEnded : IUntargetedMessage<DialogueEnded>
    {
        public GameObject speaker { get; }
    }
}
"""


@dataclass(frozen=True)
class Snippet:
    page: Path
    line: int
    target: str
    shape: str
    parameters: str
    body: str

    def source(self, index: int) -> str:
        name = f"DocSnippet{index}"
        imports = "using WallstopStudios.DxAudio;\n"
        if self.target != "core":
            imports += "using UnityEngine;\n"
        if self.target == "integration":
            imports += (
                "using System;\n"
                "using DxMessaging.Core;\n"
                "using DxMessaging.Core.Extensions;\n"
                "using WallstopStudios.DxAudio.Integration;\n"
            )
        body = f'#line {self.line} "{self.page.as_posix()}"\n{self.body}\n#line default\n'
        if self.shape == "file":
            content = body
        else:
            base = "" if self.target == "core" else " : MonoBehaviour"
            if self.shape == "members":
                content = f"{imports}public sealed class {name}{base}\n{{\n{body}}}\n"
            else:
                returns = "void"
                if self.shape == "async":
                    if self.target != "integration":
                        imports += "using System;\n"
                    imports += "using System.Threading.Tasks;\n"
                    returns = "async Task"
                content = (
                    f"{imports}public sealed class {name}{base}\n{{\n"
                    f"public {returns} Example({self.parameters})\n{{\n{body}}}\n}}\n"
                )
        return (
            "// <auto-generated/>\n"
            f"namespace WallstopStudios.DxAudio.Documentation.Snippet{index}\n"
            f"{{\n{content}}}\n"
        )


def read_page(page: Path, root: Path) -> list[Snippet]:
    relative = page.relative_to(root).as_posix()
    lines = page.read_text(encoding="utf-8").splitlines()
    snippets: list[Snippet] = []
    context = ""
    opening = ""
    language = ""
    start = 0
    footer = False

    for index, line in enumerate(lines):
        match = FENCE.fullmatch(line)
        if opening:
            if (
                match
                and match[1][0] == opening[0]
                and len(opening) <= len(match[1])
                and not match[2].strip()
            ):
                if language in CSHARP:
                    metadata = CONTEXT.fullmatch(context)
                    if metadata is None:
                        raise ValueError(f"{relative}:{start}: C# fence needs a snippet context.")
                    target, shape, parameters = metadata[1], metadata[2], metadata[3] or ""
                    body = "\n".join(lines[start:index])
                    if not body.strip() or (shape in {"file", "members"} and parameters):
                        raise ValueError(f"{relative}:{start}: Invalid C# snippet body or context.")
                    snippets.append(Snippet(page, start + 1, target, shape, parameters, body))
                opening = ""
                context = ""
            continue
        if match:
            info = match[2].split()
            opening, language = match[1], info[0].lower() if info else ""
            start = index + 1
            if context.startswith("<!-- snippet:") and language not in CSHARP:
                raise ValueError(f"{relative}:{start}: Snippet context needs a C# fence.")
        elif line.strip():
            if context.startswith("<!-- snippet:"):
                raise ValueError(f"{relative}:{index + 1}: Snippet context needs a C# fence.")
            context = line.strip()
            footer |= context == FOOTER

    if opening and language in CSHARP:
        raise ValueError(f"{relative}:{start}: C# fence has no closing delimiter.")
    if context.startswith("<!-- snippet:"):
        raise ValueError(f"{relative}: Snippet context needs a C# fence.")
    if bool(snippets) != footer:
        raise ValueError(f"{relative}: The snippet footer must match the presence of C# examples.")
    return snippets


def extract(root: Path) -> list[Snippet]:
    pages = [root / "README.md", *sorted((root / "Documentation~").rglob("*.md"))]
    snippets = [snippet for page in pages for snippet in read_page(page, root)]
    for target in ("core", "unity", "integration"):
        if not any(snippet.target == target for snippet in snippets):
            raise ValueError(f"No documentation examples found for {target}.")
    return snippets


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=ROOT, type=Path)
    parser.add_argument("--target", required=True, choices=("core", "unity"))
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--with-integration", action="store_true")
    args = parser.parse_args()
    if args.with_integration and args.target != "unity":
        parser.error("--with-integration requires --target unity")

    try:
        snippets = extract(args.root.resolve())
    except (OSError, ValueError) as error:
        parser.exit(1, f"{error}\n")

    args.output.mkdir(parents=True, exist_ok=True)
    for stale in args.output.glob("DocSnippet*.cs"):
        stale.unlink()
    targets = {args.target}
    if args.with_integration:
        targets.add("integration")
        (args.output / "DocSnippetDialogueMessages.cs").write_text(
            DIALOGUE_MESSAGES, encoding="utf-8"
        )
    count = 0
    for index, snippet in enumerate(snippets, 1):
        if snippet.target in targets:
            (args.output / f"DocSnippet{index}.cs").write_text(
                snippet.source(index), encoding="utf-8"
            )
            count += 1
    print(
        f"Generated {count} of {len(snippets)} C# documentation examples ({', '.join(sorted(targets))})."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
